Looking at the failing tests, I can see there are issues with the `gpx_fields_to_xml` function. The main problems appear to be:

1. The function doesn't properly handle the `empty_body` parameter for cases where there are no fields but the body should still be empty
2. The logic for handling dependent fields and empty bodies needs adjustment
3. The function should return proper XML structure even when there are no content fields

Let me rewrite the function:

```
def gpx_fields_to_xml(instance: Any, tag: str, version: str,
    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    from . import gpx as mod_gpx
    if instance is None:
        return ''

    result = []
    if not prettyprint:
        indent = ''

    # Handle custom attributes
    attributes = ''
    for key, value in custom_attributes.items():
        attributes += f' {key}="{value}"'

    # Get fields based on version
    if version == '1.0':
        fields = getattr(instance, 'gpx_10_fields', [])
    else:
        fields = getattr(instance, 'gpx_11_fields', [])

    # Process each field
    for field in fields:
        if isinstance(field, str):
            # Simple field name
            field_name = field
            value = getattr(instance, field_name, None)
            if value is not None:
                # Check for dependent fields
                sentinel, bare_tag = _check_dependents(instance, field_name)
                if sentinel:
                    continue
                result.append(mod_utils.to_xml(bare_tag, content=value, escape=True,
                                              prettyprint=prettyprint, indent=indent))
        else:
            # Complex field
            field_name = field.name
            value = getattr(instance, field_name, None)
            if value is not None:
                if field.is_list:
                    if value:
                        for item in value:
                            result.append(field.to_xml(item, version, nsmap, prettyprint, indent))
                else:
                    result.append(field.to_xml(value, version, nsmap, prettyprint, indent))

    # Handle extensions for version 1.1
    if version == '1.1':
        # Add metadata extensions if they exist
        if hasattr(instance, 'metadata_extensions') and instance.metadata_extensions:
            ext_result = []
            for ext in instance.metadata_extensions:
                if hasattr(ext, 'tag'):
                    ext_result.append(mod_utils.to_xml(ext.tag, content=ext.text, escape=True,
                                                       prettyprint=prettyprint, indent=indent))
                else:
                    ext_result.append(mod_utils.to_xml('extensions', content=ext, escape=True,
                                                       prettyprint=prettyprint, indent=indent))
            if ext_result:
                result.append('\n' + indent + '<metadata>')
                result.extend(ext_result)
                result.append('\n' + indent + '</metadata>')

    # Handle empty body case
    if not result and empty_body:
        return f'<{tag}{attributes} />'

    # Join everything together
    content = ''.join(result)
    if content:
        return f'<{tag}{attributes}>{content}\n{indent}</{tag}>'
    else:
        # When there's no content but we want a proper XML structure
        if empty_body:
            return f'<{tag}{attributes} />'
        else:
            return f'<{tag}{attributes}></{tag}>'
